<?php
require __DIR__.'/../../src/bootstrap.php';require __DIR__.'/../../src/dispatch_job.php';$u=require_user(['operator','admin']);$notice='';$output='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$raw=base64_decode((string)($_POST['job']??''),true);if($raw===false)fail_request('任务格式不正确。');ob_start();$job=unserialize($raw);$output=(string)ob_get_clean();if(!$job instanceof DispatchJob)fail_request('不是有效的任务文件。');db()->prepare("INSERT INTO jobs(user_id,title,status,details) VALUES(?,?,'completed',?)")->execute([$u['id'],'导入巡检任务',$output]);$notice='任务已导入并执行。';}
$normal=new DispatchJob();$example=base64_encode(serialize($normal));$rows=db()->query('SELECT id,title,status,details FROM jobs ORDER BY id DESC LIMIT 20')->fetchAll();
page('运营任务中心',function()use($notice,$output,$example,$rows){echo '<section class="panel"><h2>导入任务</h2>';if($notice)echo '<div class="notice">'.h($notice).'</div>';echo '<form method="post">'.csrf_field().'<label>任务数据<textarea name="job" required>'.h($example).'</textarea></label><button>导入并执行</button></form><pre>'.h($output).'</pre></section><section class="panel"><h2>近期任务</h2><table><thead><tr><th>编号</th><th>任务</th><th>状态</th><th>结果</th></tr></thead><tbody>';foreach($rows as$r)echo '<tr><td>'.(int)$r['id'].'</td><td>'.h($r['title']).'</td><td>'.h($r['status']).'</td><td>'.h($r['details']).'</td></tr>';echo '</tbody></table></section>';},'运营工作台');
